SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.identity_card AS "identityCard", a.person_type AS "personType", a.attendance_date AS "attendanceDate", a.work_time_range AS "workTimeRange", a.clock_in_time AS "clockInTime", a.clock_in_date AS "clockInDate", a.clock_out_time AS "clockOutTime", a.clock_out_date AS "clockOutDate", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.idle_hours AS "idleHours", a.effective_work_hours AS "effectiveWorkHours", a.daily_efficiency AS "dailyEfficiency", a.daily_achievement_rate AS "dailyAchievementRate", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_daily_attendance a
a.employee_id = #{employeeId} AND YEAR(a.attendance_date) = #{year} AND MONTH(a.attendance_date) = #{month}
ORDER BY a.attendance_date ASC

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.identity_card AS "identityCard", a.person_type AS "personType", a.attendance_date AS "attendanceDate", a.work_time_range AS "workTimeRange", a.clock_in_time AS "clockInTime", a.clock_in_date AS "clockInDate", a.clock_out_time AS "clockOutTime", a.clock_out_date AS "clockOutDate", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.idle_hours AS "idleHours", a.effective_work_hours AS "effectiveWorkHours", a.daily_efficiency AS "dailyEfficiency", a.daily_achievement_rate AS "dailyAchievementRate", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_daily_attendance a
a.employee_name = #{employeeName} AND YEAR(a.attendance_date) = #{year} AND MONTH(a.attendance_date) = #{month}
ORDER BY a.attendance_date ASC

SELECT sda.employee_id as employee_id, sda.identity_card as identity_card, DATE_FORMAT(sda.attendance_date,'%Y-%m') as monthly, sda.employee_name as employee_name, sp.phone_number as phone_number, sp.team as team, sp.job_type as job_type, SUM(CASE WHEN sda.clock_in_date IS NOT NULL THEN 1 ELSE 0 END) as attendance_date_total, CONCAT(ROUND( SUM(CASE WHEN sda.clock_in_date IS NOT NULL THEN 1 ELSE 0 END)*100/(CASE WHEN MONTH(sda.attendance_date) =2 THEN 28 WHEN MONTH(sda.attendance_date) IN (4,6,9,11) THEN 30 ELSE 31 END), 2),'%') as attendance_rate, SUM(CASE WHEN sda.attendance_normal = 0 THEN 1 ELSE 0 END) as valid_attendance_total, SUM(sda.actual_hours) as actual_hours_total, SUM(sda.idle_hours) as idle_hours_total FROM swm_daily_attendance sda LEFT JOIN swm_person sp ON sp.identity_card = sda.identity_card and sp.name= sda.employee_name
DATE_FORMAT(sda.attendance_date, '%Y-%m') = #{month}
AND sp.team = #{team}
AND a.employee_name LIKE concat('%', #{employeeName}, '%')
GROUP BY sda.employee_name LIMIT #{pageNum},#{pageSize}

SELECT COUNT(*) FROM( SELECT sda.employee_id, sda.identity_card, DATE_FORMAT(sda.attendance_date,'%Y-%m') as current_month, sda.employee_name, sp.phone_number, sp.team, sp.job_type, SUM(CASE WHEN sda.clock_in_date IS NOT NULL THEN 1 ELSE 0 END) as attendance_date_total, CONCAT(ROUND( SUM(CASE WHEN sda.clock_in_date IS NOT NULL THEN 1 ELSE 0 END)*100/(CASE WHEN MONTH(sda.attendance_date) =2 THEN 28 WHEN MONTH(sda.attendance_date) IN (4,6,9,11) THEN 30 ELSE 31 END), 2),'%') as attendance_rate, SUM(CASE WHEN sda.attendance_normal = 0 THEN 1 ELSE 0 END) as valid_attendance_total, SUM(sda.actual_hours) as actual_hours_total, SUM(sda.idle_hours) as idle_hours_total FROM swm_daily_attendance sda LEFT JOIN swm_person sp ON sp.identity_card = sda.identity_card and sp.name= sda.employee_name
DATE_FORMAT(sda.attendance_date, '%Y-%m') = #{month}
AND sp.team = #{team}
AND a.employee_name LIKE concat('%', #{employeeName}, '%')
GROUP BY sda.employee_name ) monthly_attendance

SELECT
    COUNT(1) as count
from
    swm_daily_attendance a
    left JOIN swm_person b on a.employee_id = b.id
WHERE
    b.job_type is NOT null and b.job_type != ''
  and a.attendance_date = #{date}
  and b.company = #{companyName}
  and b.department = #{workshopName}
  and b.prod_line = #{lineName}
  and b.team = #{teamName}
  and a.clock_in_time is NOT null
